; End of a bout when the time is 0
; $8310-$835a

; Two-player game only: when the time is 0, both fighters walk back to their start positions. Then a new bout starts.
check_time_out
        lda demo_mode
        ora time_left
        bne check_time_out_done
; not executed $8316-$8359
        lda two_players
        beq check_time_out_done
        lda turn_request
        bmi check_time_out_done
        lda #$80
        sta time_out_active
        ldx #$01
check_time_out_loop
        ldy fighter_facing,x
        lda fighter_x,x
        cmp fighter_home_column,y
        beq check_time_out_at_start
        lda #$82                        ; Move $02: walks back.
        cmp fighter_move,x
        beq check_time_out_next
        sta fighter_move,x
        lda #$00
        sta fighter_move_step,x
check_time_out_next
        dex
        bpl check_time_out_loop
        rts
; The fighter is at its start position: stand still. When both stand, the walk-in starts again.
check_time_out_at_start
        lda #$80
        sta fighter_move,x
        lda #$00
        sta fighter_move_step,x
        lda fighter_move
        eor fighter_move+1
        bne check_time_out_next
        sta time_out_active
        tax
        jsr reset_fighter
        inx
        txa
        jsr reset_fighter
        lda #$80
        sta walk_in_active
check_time_out_done
        rts
